// Emits ONE self-contained browser script: /home/claude/work/sandbox-setup/bundles/seed.js  (window.GZSeed over window.__z).
// Run: node zoho/sandbox/build-bundle.mjs [outfile]. The bundle inlines reset.mjs (up to its node-only marker), fields-plan.mjs and manifest.json.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname } from "node:path";

const read = (f) => readFileSync(new URL(f, import.meta.url), "utf8");
const lib = (src) => src.split("// ---- node only")[0].replace(/^import .*$/gm, "").replace(/^export /gm, "");
const manifest = JSON.parse(read("./manifest.json"));
const { deferred, ...seeded } = manifest;
const inline = { ...seeded, deferred: Object.fromEntries(Object.entries(deferred ?? {}).map(([k, d]) => [k, { reason: d.reason, rows: d.records.length }])) };

const out = `/* GZSeed — Growize sandbox seed. Generated by zoho/sandbox/build-bundle.mjs; do not edit. Sandbox org only (60090668120). Needs window.__z. */
(() => {
"use strict";
const SANDBOX_ORG_ID = "60090668120";
const MANIFEST = ${JSON.stringify(inline)};
${lib(read("./reset.mjs"))}
${lib(read("./fields-plan.mjs"))}
const z = () => { if (typeof window.__z !== "function") throw new Error("window.__z missing"); return window.__z; };
const api = () => sessionApi(z(), location.origin);
const guard = async () => {
  const org = await api().org();
  if (org.id === LIVE_ORG_ID || org.id !== SANDBOX_ORG_ID) throw new Error("not a sandbox org");
};
const codesOf = (b) => [...new Set([...(b?.fields ?? []), ...(b?.data ?? [])].map((x) => x?.code).filter(Boolean))].join(",");
const rowsOf = () => Object.fromEntries(Object.entries(MANIFEST.records).map(([m, r]) => [m, r.length]));

window.GZSeed = {
  counts: () => ({ seeded: rowsOf(), deferred: MANIFEST.deferred }),
  /** Dry run: reads the sandbox's fields and profiles, returns { steps, gaps }. Writes nothing. */
  async planFields() {
    await guard();
    const cur = {}, picks = {};
    for (const m of Object.keys(MANIFEST.records)) {
      const r = await z()("GET", "/crm/v8/settings/fields?module=" + m);
      if (r.status !== 200) { if (r.status !== 400 && r.status !== 204) throw new Error("GET fields " + m + " -> " + r.status); continue; }
      cur[m] = Object.fromEntries(r.body.fields.map((f) => [f.api_name, f.data_type]));
      // pick_list_values[].actual_value: UNVERIFIED shape (field-meta page lists the property; sample not fetched)
      picks[m] = Object.fromEntries(r.body.fields.filter((f) => f.data_type === "picklist").map((f) => [f.api_name, (f.pick_list_values ?? []).map((v) => v.actual_value)]));
    }
    const pr = await z()("GET", "/crm/v8/settings/profiles");
    if (pr.status !== 200) throw new Error("GET profiles -> " + pr.status);
    const plan = planSeedFields(MANIFEST, cur, { profiles: pr.body.profiles.map((p) => ({ id: p.id, name: p.name })) });
    return { steps: plan.steps, gaps: [...plan.gaps, ...picklistGaps(MANIFEST, picks)].map((g) => g.gap) };
  },
  /** Runs the steps in order; stops at the first non-2xx. Log has status and Zoho codes only. */
  async applyFields(steps) {
    await guard();
    const log = [];
    for (const s of steps) {
      const r = await z()(s.method, s.path, s.body);
      log.push({ why: s.why, status: r.status, codes: codesOf(r.body) });
      if (r.status < 200 || r.status >= 300) break;
    }
    return log;
  },
  /** Dry run: who would own what, what would be deleted. Writes nothing. */
  async plan({ personaEmails } = {}) {
    await guard();
    const a = api();
    const { users, fallbacks } = await resolveUsers({ api: a, personaEmails });
    const delete_ = {};
    for (const m of dependencyOrder(MANIFEST)) delete_[m] = (await a.listTagged(m, MANIFEST.tagField)).length;
    return { upsert: rowsOf(), deleteFirst: delete_, order: dependencyOrder(MANIFEST), distribution: distribution(MANIFEST), personasResolved: PERSONAS.filter((p) => !fallbacks.includes(p)), fallbacksToAdmin: fallbacks };
  },
  /** Deletes every Test_Seed record, then upserts the manifest. Without { confirm: true } it only returns plan(). */
  async reset({ personaEmails, confirm } = {}) {
    if (confirm !== true) return { dryRun: true, ...(await this.plan({ personaEmails })) };
    await guard();
    return reset({ api: api(), manifest: MANIFEST, sandboxOrgId: SANDBOX_ORG_ID, personaEmails });
  },
};
})();
`;
const dest = process.argv[2] ?? "/home/claude/work/sandbox-setup/bundles/seed.js";
mkdirSync(dirname(dest), { recursive: true });
writeFileSync(dest, out);
console.log(`wrote ${dest} (${out.length} bytes)`);
